#include <arm_neon.h>
#include <stdint.h>

void matmul(float* xout, float* x, float* w, int n, int d) {
    int i;
    #pragma omp parallel for private(i) schedule(static)
    for (i = 0; i < d; i++) {
        const float* wp = w + (size_t)i * (size_t)n;
        int j = 0;
        float32x4_t acc0 = vdupq_n_f32(0.0f);
        float32x4_t acc1 = vdupq_n_f32(0.0f);
        float32x4_t acc2 = vdupq_n_f32(0.0f);
        float32x4_t acc3 = vdupq_n_f32(0.0f);
        for (; j + 16 <= n; j += 16) {
            float32x4_t x0 = vld1q_f32(x + j);
            float32x4_t x1 = vld1q_f32(x + j + 4);
            float32x4_t x2 = vld1q_f32(x + j + 8);
            float32x4_t x3 = vld1q_f32(x + j + 12);
            acc0 = vfmaq_f32(acc0, vld1q_f32(wp + j), x0);
            acc1 = vfmaq_f32(acc1, vld1q_f32(wp + j + 4), x1);
            acc2 = vfmaq_f32(acc2, vld1q_f32(wp + j + 8), x2);
            acc3 = vfmaq_f32(acc3, vld1q_f32(wp + j + 12), x3);
        }
        for (; j + 4 <= n; j += 4) {
            acc0 = vfmaq_f32(acc0, vld1q_f32(wp + j), vld1q_f32(x + j));
        }
        acc0 = vaddq_f32(acc0, acc1);
        acc2 = vaddq_f32(acc2, acc3);
        acc0 = vaddq_f32(acc0, acc2);
        float val = vaddvq_f32(acc0);
        for (; j < n; j++) {
            val += wp[j] * x[j];
        }
        xout[i] = val;
    }
}

#include <arm_neon.h>
#include <dispatch/dispatch.h>
#include <stdint.h>

/* Dot product of one row of W with x, using 4 NEON FMA accumulators.
   Handles non-multiple-of-16 tails scalar-wise. */
static inline float dot_f32(const float* restrict wp, const float* restrict x, int n) {
    float32x4_t a0 = vdupq_n_f32(0.0f);
    float32x4_t a1 = vdupq_n_f32(0.0f);
    float32x4_t a2 = vdupq_n_f32(0.0f);
    float32x4_t a3 = vdupq_n_f32(0.0f);
    int j = 0;
    for (; j + 16 <= n; j += 16) {
        a0 = vfmaq_f32(a0, vld1q_f32(wp + j),      vld1q_f32(x + j));
        a1 = vfmaq_f32(a1, vld1q_f32(wp + j + 4),  vld1q_f32(x + j + 4));
        a2 = vfmaq_f32(a2, vld1q_f32(wp + j + 8),  vld1q_f32(x + j + 8));
        a3 = vfmaq_f32(a3, vld1q_f32(wp + j + 12), vld1q_f32(x + j + 12));
    }
    for (; j + 4 <= n; j += 4) {
        a0 = vfmaq_f32(a0, vld1q_f32(wp + j), vld1q_f32(x + j));
    }
    float32x4_t s = vaddq_f32(vaddq_f32(a0, a1), vaddq_f32(a2, a3));
    float acc = vaddvq_f32(s);
    for (; j < n; j++) acc += wp[j] * x[j];
    return acc;
}

void matmul(float* xout, float* x, float* w, int n, int d) {
    /* W (d,n) @ x (n,) -> xout (d,) : row i = sum_j w[i*n+j] * x[j] */
    if (d <= 0 || n <= 0) return;

    /* Split rows into ~4 waves over 12 cores; rows are uniform cost so a
       static chunked split is well balanced. */
    int nb = 48;
    if (d < nb) nb = d;
    int chunk = (d + nb - 1) / nb;
    nb = (d + chunk - 1) / chunk;

    const float* restrict wbase = w;
    const float* restrict xb    = x;
    float* restrict             xo = xout;

    dispatch_apply((size_t)nb,
                   dispatch_get_global_queue(DISPATCH_QUEUE_PRIORITY_HIGH, 0),
                   ^(size_t b) {
        int r0 = (int)b * chunk;
        int r1 = r0 + chunk;
        if (r1 > d) r1 = d;
        for (int i = r0; i < r1; i++) {
            xo[i] = dot_f32(wbase + (size_t)i * (size_t)n, xb, n);
        }
    });
}

#include <arm_neon.h>
#include <stdint.h>
#include <dispatch/dispatch.h>

void matmul(float* xout, float* x, float* w, int n, int d) {
    // Chunk rows; each chunk processes multiple rows, reusing x.
    const int CHUNK = 64;
    int nchunks = (d + CHUNK - 1) / CHUNK;
    if (nchunks < 1) nchunks = 1;

    dispatch_apply(nchunks, DISPATCH_APPLY_AUTO, ^(size_t ci) {
        int i0 = (int)ci * CHUNK;
        int i1 = i0 + CHUNK;
        if (i1 > d) i1 = d;
        for (int i = i0; i < i1; i++) {
            const float* wp = w + (size_t)i * n;
            float32x4_t acc0 = vdupq_n_f32(0.0f);
            float32x4_t acc1 = vdupq_n_f32(0.0f);
            float32x4_t acc2 = vdupq_n_f32(0.0f);
            float32x4_t acc3 = vdupq_n_f32(0.0f);
            int j = 0;
            for (; j + 16 <= n; j += 16) {
                acc0 = vfmaq_f32(acc0, vld1q_f32(wp + j),      vld1q_f32(x + j));
                acc1 = vfmaq_f32(acc1, vld1q_f32(wp + j + 4),  vld1q_f32(x + j + 4));
                acc2 = vfmaq_f32(acc2, vld1q_f32(wp + j + 8),  vld1q_f32(x + j + 8));
                acc3 = vfmaq_f32(acc3, vld1q_f32(wp + j + 12), vld1q_f32(x + j + 12));
            }
            for (; j + 4 <= n; j += 4) {
                acc0 = vfmaq_f32(acc0, vld1q_f32(wp + j), vld1q_f32(x + j));
            }
            float sum = vaddvq_f32(vaddq_f32(vaddq_f32(acc0, acc1), vaddq_f32(acc2, acc3)));
            for (; j < n; j++) {
                sum += wp[j] * x[j];
            }
            xout[i] = sum;
        }
    });
}

#include <arm_neon.h>
#include <stdint.h>
#include <dispatch/dispatch.h>

// Compute a block of rows [i0, i1) using 4-row NEON kernel.
static void matmul_rows(float* xout, const float* x, const float* w,
                        int n, int i0, int i1) {
    int i = i0;
    for (; i + 4 <= i1; i += 4) {
        const float* w0 = w + (size_t)(i + 0) * n;
        const float* w1 = w + (size_t)(i + 1) * n;
        const float* w2 = w + (size_t)(i + 2) * n;
        const float* w3 = w + (size_t)(i + 3) * n;

        float32x4_t a0 = vdupq_n_f32(0.f);
        float32x4_t a1 = vdupq_n_f32(0.f);
        float32x4_t a2 = vdupq_n_f32(0.f);
        float32x4_t a3 = vdupq_n_f32(0.f);

        int j = 0;
        for (; j + 16 <= n; j += 16) {
            float32x4_t x0 = vld1q_f32(x + j);
            float32x4_t x1 = vld1q_f32(x + j + 4);
            float32x4_t x2 = vld1q_f32(x + j + 8);
            float32x4_t x3 = vld1q_f32(x + j + 12);
            a0 = vfmaq_f32(a0, vld1q_f32(w0 + j),      x0);
            a0 = vfmaq_f32(a0, vld1q_f32(w0 + j + 4),  x1);
            a0 = vfmaq_f32(a0, vld1q_f32(w0 + j + 8),  x2);
            a0 = vfmaq_f32(a0, vld1q_f32(w0 + j + 12), x3);
            a1 = vfmaq_f32(a1, vld1q_f32(w1 + j),      x0);
            a1 = vfmaq_f32(a1, vld1q_f32(w1 + j + 4),  x1);
            a1 = vfmaq_f32(a1, vld1q_f32(w1 + j + 8),  x2);
            a1 = vfmaq_f32(a1, vld1q_f32(w1 + j + 12), x3);
            a2 = vfmaq_f32(a2, vld1q_f32(w2 + j),      x0);
            a2 = vfmaq_f32(a2, vld1q_f32(w2 + j + 4),  x1);
            a2 = vfmaq_f32(a2, vld1q_f32(w2 + j + 8),  x2);
            a2 = vfmaq_f32(a2, vld1q_f32(w2 + j + 12), x3);
            a3 = vfmaq_f32(a3, vld1q_f32(w3 + j),      x0);
            a3 = vfmaq_f32(a3, vld1q_f32(w3 + j + 4),  x1);
            a3 = vfmaq_f32(a3, vld1q_f32(w3 + j + 8),  x2);
            a3 = vfmaq_f32(a3, vld1q_f32(w3 + j + 12), x3);
        }
        for (; j + 4 <= n; j += 4) {
            float32x4_t x0 = vld1q_f32(x + j);
            a0 = vfmaq_f32(a0, vld1q_f32(w0 + j), x0);
            a1 = vfmaq_f32(a1, vld1q_f32(w1 + j), x0);
            a2 = vfmaq_f32(a2, vld1q_f32(w2 + j), x0);
            a3 = vfmaq_f32(a3, vld1q_f32(w3 + j), x0);
        }
        float s0 = vaddvq_f32(a0);
        float s1 = vaddvq_f32(a1);
        float s2 = vaddvq_f32(a2);
        float s3 = vaddvq_f32(a3);
        for (; j < n; j++) {
            float xj = x[j];
            s0 += w0[j] * xj;
            s1 += w1[j] * xj;
            s2 += w2[j] * xj;
            s3 += w3[j] * xj;
        }
        xout[i + 0] = s0;
        xout[i + 1] = s1;
        xout[i + 2] = s2;
        xout[i + 3] = s3;
    }
    for (; i < i1; i++) {
        const float* wi = w + (size_t)i * n;
        float32x4_t a = vdupq_n_f32(0.f);
        float32x4_t b = vdupq_n_f32(0.f);
        int j = 0;
        for (; j + 8 <= n; j += 8) {
            a = vfmaq_f32(a, vld1q_f32(wi + j),     vld1q_f32(x + j));
            b = vfmaq_f32(b, vld1q_f32(wi + j + 4), vld1q_f32(x + j + 4));
        }
        for (; j + 4 <= n; j += 4) {
            a = vfmaq_f32(a, vld1q_f32(wi + j), vld1q_f32(x + j));
        }
        float s = vaddvq_f32(vaddq_f32(a, b));
        for (; j < n; j++) s += wi[j] * x[j];
        xout[i] = s;
    }
}

// Greedy-argmax threshold: multithreading only pays off for large d.
#define MM_PARALLEL_MIN_D 512
#define MM_GRAIN 64

void matmul(float* xout, float* x, float* w, int n, int d) {
    if (d < MM_PARALLEL_MIN_D) {
        matmul_rows(xout, x, w, n, 0, d);
        return;
    }

    // Partition rows into 4-row-aligned chunks for dispatch_apply.
    int nchunks = (d + MM_GRAIN - 1) / MM_GRAIN;
    int chunk = ((d + nchunks - 1) / nchunks + 3) & ~3;
    int total = (d + chunk - 1) / chunk;

    dispatch_apply(total, DISPATCH_APPLY_AUTO, ^(size_t k) {
        int i0 = (int)k * chunk;
        int i1 = i0 + chunk;
        if (i1 > d) i1 = d;
        matmul_rows(xout, x, w, n, i0, i1);
    });
}
